import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: what the office charges as base premium for the items a
 * policy covers. Main items are priced individually; every component costs the
 * same per-component rate whichever type it is, and a building block of alike
 * components is offered at a special rate.
 *
 * The per-component rate ignores the component's type, but the block rate does
 * not: a block is a quantity of <em>alike</em> components, so the tariff also
 * decides which items count as alike (see {@link #alikenessGroupOf}) and groups
 * them before pricing.
 *
 * This is the office's tariff. It changes on its own schedule, independently of
 * the modifier rules in {@link PremiumPolicy}.
 */
public class PriceList {

    private static final Map<String, BigDecimal> MAIN_ITEM_BASE_PREMIUM = Map.of(
            "sword", new BigDecimal("100"),
            "amulet", new BigDecimal("60"),
            "staff", new BigDecimal("80"),
            "potion", new BigDecimal("40"));

    /** Components are all priced at one rate per component, whatever their type. */
    private static final BigDecimal COMPONENT_BASE_PREMIUM = new BigDecimal("25");

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    /** A building block of exactly 3 alike components is offered at this rate. */
    private static final BigDecimal COMPONENT_BLOCK_BASE_PREMIUM = new BigDecimal("60");
    private static final int COMPONENT_BLOCK_SIZE = 3;

    /** The base premium for all items a policy covers, alike items priced together. */
    public BigDecimal policyBasePremium(List<String> insuredItemTypes) {
        BigDecimal total = BigDecimal.ZERO;
        for (Map.Entry<String, Integer> alikeItems : groupedByAlikeness(insuredItemTypes).entrySet()) {
            total = total.add(basePremium(alikeItems.getKey(), alikeItems.getValue()));
        }
        return total;
    }

    private static Map<String, Integer> groupedByAlikeness(List<String> insuredItemTypes) {
        Map<String, Integer> counts = new LinkedHashMap<>();
        for (String itemType : insuredItemTypes) {
            counts.merge(alikenessGroupOf(itemType), 1, Integer::sum);
        }
        return counts;
    }

    /**
     * The office counts two items as alike when they are of exactly the same
     * type, not merely of the same family: 2 runes and a moonstone are three
     * loose components priced at 75 G, never a block, because a moonstone is not
     * a rune. Widening "alike" to a family (rune-y, gemstone-y) would mean
     * returning a family name here instead of the type itself.
     */
    private static String alikenessGroupOf(String itemType) {
        return itemType;
    }

    private static BigDecimal basePremium(String itemType, int count) {
        if (COMPONENT_TYPES.contains(itemType)) {
            return componentsBasePremium(count);
        }
        return MAIN_ITEM_BASE_PREMIUM.get(itemType).multiply(BigDecimal.valueOf(count));
    }

    private static BigDecimal componentsBasePremium(int count) {
        if (qualifiesForBlockRate(count)) {
            return COMPONENT_BLOCK_BASE_PREMIUM;
        }
        return COMPONENT_BASE_PREMIUM.multiply(BigDecimal.valueOf(count));
    }

    /**
     * The office grants the block rate only to a holding of exactly 3 alike
     * components. It neither prices a part of a block at the block rate (4
     * components are not a block) nor breaks a larger holding down into blocks
     * (7 components are priced as 7, not as two blocks and one loose component).
     */
    private static boolean qualifiesForBlockRate(int alikeComponentCount) {
        return alikeComponentCount == COMPONENT_BLOCK_SIZE;
    }
}
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * The MHPCO premium rules: policy-wide modifiers, the processing fee, and
 * rounding in the office's favor, applied to the base premium the
 * {@link PriceList} states for the insured items.
 *
 * Intermediate amounts stay exact fractions; only the final premium is rounded.
 */
public class PremiumPolicy {

    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");

    private final PriceList priceList = new PriceList();

    public int quote(List<String> insuredItemTypes) {
        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItemTypes);
        BigDecimal withPolicyModifiers = policyBasePremium
                .add(policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE));
        return inOfficesFavor(withPolicyModifiers.add(PROCESSING_FEE));
    }

    private int inOfficesFavor(BigDecimal premium) {
        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    }
}
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.List;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

/**
 * Translates the JSON scenario protocol into MHPCO operations and back.
 * The protocol field names are binding; the premium rules live in
 * {@link PremiumPolicy}.
 */
public class ClaimOfficeCli {

    private static final ObjectMapper JSON = new ObjectMapper();

    private final PremiumPolicy premiumPolicy = new PremiumPolicy();

    public void run(InputStream scenario, PrintStream results) {
        try {
            JsonNode input = JSON.readTree(scenario);
            ObjectNode output = JSON.createObjectNode();
            ArrayNode resultsNode = output.putArray("results");
            for (JsonNode step : input.get("steps")) {
                resultsNode.addObject().put("premium", premiumPolicy.quote(insuredItemTypes(step)));
            }
            results.print(JSON.writeValueAsString(output));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static List<String> insuredItemTypes(JsonNode quoteStep) {
        List<String> types = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            types.add(item.get("type").asText());
        }
        return types;
    }
}

