import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.List;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

/**
 * Translates the JSON scenario protocol into MHPCO operations and back.
 * The protocol field names are binding; the premium rules live in
 * {@link PremiumPolicy}.
 */
public class ClaimOfficeCli {

    private static final ObjectMapper JSON = new ObjectMapper();

    private final PremiumPolicy premiumPolicy = new PremiumPolicy();

    public void run(InputStream scenario, PrintStream results) {
        try {
            JsonNode input = JSON.readTree(scenario);
            int yearsWithMHPCO = input.get("customer").get("yearsWithMHPCO").asInt();
            ObjectNode output = JSON.createObjectNode();
            ArrayNode resultsNode = output.putArray("results");
            int contractsAlreadyHeld = 0;
            for (JsonNode step : input.get("steps")) {
                Customer customer = new Customer(yearsWithMHPCO, contractsAlreadyHeld);
                resultsNode.addObject().put("premium",
                        premiumPolicy.quote(customer, insuredItems(step)));
                contractsAlreadyHeld++;
            }
            results.print(JSON.writeValueAsString(output));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
        List<InsuredItem> items = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            items.add(new InsuredItem(item.get("type").asText(),
                    item.path("cursed").asBoolean(false),
                    item.path("enchantment").asInt(0)));
        }
        return items;
    }
}
=====PRICELIST=====
