import java.math.BigDecimal;
import java.util.List;

/**
 * A policy the office has written: the items it covers and how much of its
 * payout cap is left. The cap is twice the insurance sum and is not raised by
 * premium modifiers.
 *
 * Settling an incident against the policy is this policy's decision, not the
 * protocol's: the office reimburses every reported damage on its own terms (the
 * {@link ClaimPolicy} states what one damage earns) and pays out only what the
 * cap still allows, so the deductible is borne once per damage reported and the
 * cap is consumed in the order the damages are reported.
 */
public class Policy {

    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");

    private BigDecimal remainingCap;

    public Policy(BigDecimal insuranceSum) {
        this.remainingCap = insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM);
    }

    /**
     * What the office pays for one reported incident: every damage reimbursed on
     * its own terms, the total limited to the cap the policy has left.
     */
    public BigDecimal settle(List<BigDecimal> damageAmounts, ClaimPolicy claimPolicy) {
        BigDecimal paid = BigDecimal.ZERO;
        for (BigDecimal damageAmount : damageAmounts) {
            paid = paid.add(payWithinCap(claimPolicy.reimbursementFor(damageAmount)));
        }
        return paid;
    }

    /** Pays what the cap still allows and records the rest as exhausted. */
    private BigDecimal payWithinCap(BigDecimal desiredPayout) {
        BigDecimal paid = desiredPayout.min(remainingCap);
        remainingCap = remainingCap.subtract(paid);
        return paid;
    }

    public BigDecimal remainingCap() {
        return remainingCap;
    }
}
import java.math.BigDecimal;

/**
 * The MHPCO claim rules: what the office reimburses for a damage report against
 * a policy, after the deductible and within the policy's payout cap.
 *
 * A payout is a payment out of the office, so its fraction of a G is rounded in
 * the office's favor by {@link InOfficesFavor}.
 */
public class ClaimPolicy {

    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = new BigDecimal("100");

    /** The office reimburses damage less the deductible, never below nothing. */
    public BigDecimal reimbursementFor(BigDecimal damageAmount) {
        BigDecimal reimbursed = damageAmount.subtract(DEDUCTIBLE_PER_DAMAGE);
        return InOfficesFavor.payment(reimbursed.max(BigDecimal.ZERO));
    }
}
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * The MHPCO rounds every amount to whole G in its own favor. One rule, read in
 * the direction the money moves: a fraction of a G the customer owes the office
 * is rounded up, a fraction the office owes the customer is rounded down. The
 * office never loses the fraction.
 *
 * Intermediate amounts during a calculation stay exact fractions; only a final
 * charge or payment is rounded.
 */
final class InOfficesFavor {

    private static final int WHOLE_G = 0;

    private InOfficesFavor() {
    }

    /** What the customer owes the office, rounded up: the fraction favors the office. */
    static BigDecimal charge(BigDecimal amount) {
        return amount.setScale(WHOLE_G, RoundingMode.CEILING);
    }

    /** What the office owes the customer, rounded down: the fraction favors the office. */
    static BigDecimal payment(BigDecimal amount) {
        return amount.setScale(WHOLE_G, RoundingMode.FLOOR);
    }
}
